function coinChange(coins, amount) {
  // Breadth-first search over amounts: level = number of coins used.
  if (amount === 0) return 0;
  const seen = new Uint8Array(amount + 1);
  seen[0] = 1;
  let frontier = [0];
  for (let used = 1; frontier.length; used++) {
    const next = [];
    for (const a of frontier) {
      for (const c of coins) {
        const b = a + c;
        if (b === amount) return used;
        if (b < amount && !seen[b]) { seen[b] = 1; next.push(b); }
      }
    }
    frontier = next;
  }
  return -1;
}

